<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue'
onMounted(() => { const observer = new MutationObserver(() => { const actions = document.querySelector('.admin-order-actions'); if (!actions || actions.querySelector('.admin-preparation-update')) return; if (selected.value?.estado !== 'PREPARANDO') return; const button = document.createElement('button'); button.className = 'admin-preparation-update'; button.textContent = 'Actualizar tiempo de preparación'; button.addEventListener('click', () => transition(selected.value, 'ACTUALIZAR_PREPARACION')); actions.prepend(button) }); observer.observe(document.body, { childList: true, subtree: true }); onBeforeUnmount(() => observer.disconnect()) })
import { Check, Clock3, RefreshCw, X } from 'lucide-vue-next'
import CancelOrderModal from '../components/CancelOrderModal.vue'
import { acceptOrder, cancelAdminOrder, loadAdminOrders, markOrderReady, publishCourierRequest, rejectOrder, subscribeToOrders, updateOrderState, updatePreparationTime } from '../services/adminOperationsService'
const orders = ref([]); const selected = ref(null); const status = ref(''); const loading = ref(true); const error = ref(''); const notice = ref(''); const cancelOpen = ref(false); const cancelling = ref(false); let unsubscribe
const statuses = ['', 'PENDIENTE_ACEPTACION', 'PREPARANDO', 'LISTO_PARA_RECOGER', 'ASIGNADO', 'RECOGIDO', 'EN_CAMINO', 'ENTREGADO', 'CANCELADO']
async function load() { loading.value = true; try { orders.value = await loadAdminOrders(status.value) } catch (e) { error.value = e.message || 'No se pudieron cargar los pedidos.' } finally { loading.value = false } }
function preparationMinutes(title = '¿Cuánto tiempo tardará en estar listo el pedido?') { return new Promise((resolve) => { const overlay = document.createElement('div'); overlay.className = 'admin-preparation-modal'; overlay.innerHTML = `<div class="admin-preparation-modal__card" role="dialog" aria-modal="true"><button class="admin-preparation-modal__close" aria-label="Cerrar">×</button><span class="admin-eyebrow">TIEMPO DE PREPARACIÓN</span><h3>${title}</h3><p>Selecciona una opción para continuar.</p><div class="admin-preparation-options">${[5, 10, 15, 20, 25, 30].map((minutes) => `<button data-minutes="${minutes}">${minutes} min</button>`).join('')}</div><label class="admin-preparation-custom">Tiempo personalizado<input type="number" min="1" max="1440" placeholder="Minutos" /></label><button class="admin-preparation-confirm">Confirmar tiempo</button><p class="admin-preparation-error" aria-live="polite"></p></div>`; const close = (value = null) => { overlay.remove(); resolve(value) }; overlay.addEventListener('click', (event) => { if (event.target === overlay || event.target.closest('.admin-preparation-modal__close')) close() }); const card = overlay.querySelector('.admin-preparation-modal__card'); let selected = null; card.querySelectorAll('[data-minutes]').forEach((button) => button.addEventListener('click', () => { selected = Number(button.dataset.minutes); card.querySelectorAll('[data-minutes]').forEach((item) => item.classList.toggle('active', item === button)); card.querySelector('input').value = '' })); card.querySelector('input').addEventListener('input', (event) => { selected = Number(event.target.value); card.querySelectorAll('[data-minutes]').forEach((item) => item.classList.remove('active')) }); card.querySelector('.admin-preparation-confirm').addEventListener('click', () => { if (Number.isInteger(selected) && selected > 0 && selected <= 1440) close(selected); else card.querySelector('.admin-preparation-error').textContent = 'Selecciona un tiempo válido entre 1 y 1440 minutos.' }); document.body.append(overlay) }) }
async function transition(order, next) { error.value = ''; try { if (next === 'ACEPTAR') { const minutes = await preparationMinutes(); if (minutes == null) { error.value = 'Selecciona un tiempo válido antes de aceptar.'; return }; await acceptOrder(order.id, minutes) } else if (next === 'ACTUALIZAR_PREPARACION') { const minutes = await preparationMinutes('¿Cuántos minutos faltan para que esté listo el pedido?'); if (minutes == null) { error.value = 'Escribe un tiempo válido para actualizar la preparación.'; return }; await updatePreparationTime(order.id, minutes) } else if (next === 'RECHAZAR') { cancelOpen.value = true; return } else if (next === 'LISTO') await markOrderReady(order.id); else if (next === 'PUBLICAR') await publishCourierRequest(order.id); else await updateOrderState(order.id, next); notice.value = next === 'PUBLICAR' ? `Pedido #${order.numero} publicado para repartidores.` : `Pedido #${order.numero} actualizado.`; await load(); selected.value = orders.value.find((item) => item.id === order.id) || null } catch (e) { const message = e?.message || ''; error.value = message.includes('ROL_NO_AUTORIZADO') ? 'Solo un administrador puede solicitar repartidor.' : message.includes('TIEMPO_PREPARACION_INVALIDO') ? 'El tiempo de preparación no es válido.' : message.includes('PEDIDO_NO_PUBLICABLE') || message.includes('SOLICITUD_NO_DISPONIBLE') ? 'El pedido ya no está listo para solicitar repartidor o ya fue publicado.' : message || 'La transición no está permitida por el flujo actual.' } }
async function cancelSelected({ motivo, descripcion }) { if (!selected.value) return; cancelling.value = true; error.value = ''; try { const result = await cancelAdminOrder(selected.value.id, motivo, descripcion); if (result?.duplicado) notice.value = 'El pedido ya estaba cancelado.'; else notice.value = result?.reembolso_estado === 'SIMULADO_COMPLETADO' ? 'Pedido cancelado y reembolso automático registrado.' : result?.reembolso_estado === 'REVISION_MANUAL' ? 'Pedido cancelado y reembolso enviado a revisión.' : 'Pedido cancelado sin devolución.'; cancelOpen.value = false; await load(); selected.value = orders.value.find((item) => item.id === selected.value?.id) || null } catch (e) { const message = e?.message || ''; error.value = message.includes('DESCRIPCION_REQUERIDA') ? 'La descripción es obligatoria para OTRO.' : message || 'No se pudo cancelar el pedido.' } finally { cancelling.value = false } }
onMounted(async () => { await load(); unsubscribe = subscribeToOrders(load) }); onBeforeUnmount(() => unsubscribe?.())
</script>
<template>
  <section class="admin-view"><div class="admin-view-heading"><div><span class="admin-eyebrow">OPERACIÓN EN TIEMPO REAL</span><h2>Pedidos</h2><p>La bandeja se actualiza cuando Supabase registra cambios.</p></div><button class="admin-icon-button" @click="load"><RefreshCw :size="18" /></button></div>
    <div class="admin-toolbar"><select v-model="status" @change="load"><option v-for="item in statuses" :key="item" :value="item">{{ item || 'Todos los estados' }}</option></select><span>{{ orders.length }} pedidos</span></div><p v-if="error" class="admin-alert">{{ error }}</p><p v-if="notice" class="admin-success">{{ notice }}</p><div v-if="loading" class="admin-empty">Cargando pedidos…</div><div v-else-if="!orders.length" class="admin-empty">No hay pedidos para este filtro.</div>
    <div v-else class="admin-panel admin-table-wrap"><table class="admin-table"><thead><tr><th>Número</th><th>Restaurante</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Estado</th><th /></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td>#{{ order.numero }}</td><td>{{ order.restaurantes?.nombre || '—' }}</td><td>{{ order.perfiles?.nombre || '—' }}</td><td>{{ new Date(order.created_at).toLocaleString('es-SV', { dateStyle: 'short', timeStyle: 'short' }) }}</td><td>${{ Number(order.total).toFixed(2) }}</td><td><span class="admin-status-pill" :data-status="order.estado">{{ order.estado }}</span></td><td><button class="admin-link-button" @click="selected = order">Ver detalle</button></td></tr></tbody></table></div>
    <div v-if="selected" class="admin-drawer-backdrop" @click.self="selected = null"><aside class="admin-order-drawer"><button class="admin-drawer-close" @click="selected = null"><X :size="20" /></button><span class="admin-eyebrow">PEDIDO #{{ selected.numero }}</span><h3>{{ selected.restaurantes?.nombre }}</h3><p>{{ selected.perfiles?.nombre || 'Cliente' }}</p><div class="admin-order-lines"><div v-for="line in selected.pedido_detalles" :key="line.id"><span>{{ line.cantidad }} × {{ line.nombre_producto_snapshot }}</span><strong>${{ Number(line.subtotal_linea).toFixed(2) }}</strong></div></div><dl class="admin-order-meta"><div><dt>Dirección</dt><dd>{{ selected.direccion_snapshot }}</dd></div><div><dt>Estado</dt><dd>{{ selected.estado }}</dd></div><div><dt>Método de pago</dt><dd>{{ selected.metodo_pago === 'TARJETA_SIMULADA' ? 'Tarjeta simulada' : 'Efectivo' }}</dd></div><div><dt>Estado de pago</dt><dd>{{ selected.estado_pago || 'PENDIENTE' }}</dd></div><div><dt>Repartidor</dt><dd>{{ selected.asignaciones?.[0]?.repartidores?.perfiles?.nombre || 'Sin asignar' }}</dd></div></dl><strong class="admin-order-total">Total: ${{ Number(selected.total).toFixed(2) }}</strong><div class="admin-order-actions"><button v-if="selected.estado === 'PENDIENTE_ACEPTACION'" @click="transition(selected, 'ACEPTAR')"><Check :size="17" /> Aceptar pedido</button><button v-if="!['ENTREGADO', 'CANCELADO'].includes(selected.estado)" class="admin-danger-button" @click="transition(selected, 'RECHAZAR')"><X :size="17" /> Cancelar pedido</button><button v-if="selected.estado === 'PREPARANDO'" @click="transition(selected, 'LISTO')"><Check :size="17" /> Marcar como listo</button><button v-if="selected.estado === 'LISTO_PARA_RECOGER'" @click="transition(selected, 'PUBLICAR')"><Clock3 :size="17" /> Solicitar repartidor</button><button v-if="selected.estado === 'ASIGNADO'" @click="transition(selected, 'RECOGIDO')"><Check :size="17" /> Marcar recogido</button><button v-if="selected.estado === 'RECOGIDO'" @click="transition(selected, 'EN_CAMINO')"><Clock3 :size="17" /> Marcar en camino</button><button v-if="selected.estado === 'EN_CAMINO'" @click="transition(selected, 'ENTREGADO')"><Check :size="17" /> Marcar entregado</button></div></aside></div>
    <CancelOrderModal v-model="cancelOpen" role="admin" :order="selected" :busy="cancelling" @close="cancelOpen = false" @confirm="cancelSelected" />
  </section>
</template>
